//! Extraction of files written by an authoring tool (IF-222 f). The deck and
//! the document were generated by pandoc 3.14 from the Markdown sources next
//! to them in `examples/fixtures/`; see the README there.

use ironflow::{engine::types::Context, nodes::NodeRegistry};
use serde_json::json;

fn fixture(name: &str) -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("examples/fixtures")
        .join(name)
}

async fn run(node: &str, config: serde_json::Value) -> ironflow::engine::types::NodeOutput {
    NodeRegistry::with_builtins()
        .get(node)
        .unwrap()
        .execute(&config, &Context::new())
        .await
        .unwrap()
}

#[tokio::test]
async fn a_pandoc_deck_extracts_titles_text_and_speaker_notes() {
    let path = fixture("pandoc-deck.pptx");
    let output = run("extract_pptx", json!({"path": path, "format": "markdown"})).await;
    assert_eq!(
        output["content"],
        "## Slide 1\n\n### Tool Deck\n\nIronFlow tests\n\n\
         ## Slide 2\n\n### First slide\n\n- Bullet one\n- Bullet two\n\n\
         **Speaker notes:**\nFirst note line\n\nSecond note paragraph with bold\nand a hard break\n\n\
         ## Slide 3\n\n### Second slide\n\nBody text line one\nline two after break\n\n\
         ## Slide 4\n\n### Third slide\n\nText only\n\n\
         **Speaker notes:**\nThird slide note"
    );

    let output = run("extract_pptx", json!({"path": path, "format": "json"})).await;
    let slides = output["content"]["slides"].as_array().unwrap();
    assert_eq!(slides.len(), 4);
    // The slide-number field of the notes page is not notes text.
    assert_eq!(slides[3]["speaker_notes"], "Third slide note");
    for index in [0, 2] {
        assert!(
            slides[index].get("speaker_notes").is_none(),
            "{}",
            slides[index]
        );
    }
}

#[tokio::test]
async fn a_pandoc_document_extracts_formatting_comments_and_tracked_text() {
    let path = fixture("pandoc-document.docx");
    let output = run(
        "extract_word",
        json!({
            "path": path,
            "format": "markdown",
            "metadata_key": "metadata",
            "comments_key": "comments"
        }),
    )
    .await;
    // The tracked insertion is read as accepted and the deletion as gone.
    assert_eq!(
        output["content"],
        "# Tool Document\n\nIronFlow tests\n\n# Heading\n\n\
         Plain paragraph with anchored words after it.\n\
         A paragraph with **bold**, *italic* and ~~struck~~ text\nand a hard line break.\n\
         inserted text and  tracked.\n\n| A | B |\n| --- | --- |\n| 1 | 2 |"
    );
    assert_eq!(output["metadata"]["title"], "Tool Document");
    assert_eq!(output["metadata"]["author"], "IronFlow tests");
    assert_eq!(
        output["comments"],
        json!([{
            "id": "0",
            "author": "Reviewer",
            "date": "2026-11-15T00:00:00Z",
            "text": "Reviewer note one",
            "anchored_text": "anchored words"
        }])
    );

    let output = run("extract_word", json!({"path": path, "format": "json"})).await;
    let blocks = output["content"]["blocks"].as_array().unwrap();
    assert_eq!(blocks[0]["style"], "Title");
    assert_eq!(blocks[2]["style"], "Heading1");
    let flagged = |key: &str| {
        blocks[4]["runs"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|run| run[key] == true)
            .map(|run| run["text"].as_str().unwrap())
            .collect::<Vec<_>>()
    };
    assert_eq!(flagged("bold"), ["bold"]);
    assert_eq!(flagged("italic"), ["italic"]);
    assert_eq!(flagged("strike"), ["struck"]);
}
